<?php
namespace Tests\Feature\Settings; use App\Models\{Setting,User}; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class SettingsTest extends TestCase { use RefreshDatabase; public function test_settings_are_role_protected_and_update_registry_values():void{$this->get('/admin/settings')->assertRedirect('/login');$this->actingAs(User::factory()->create())->get('/admin/settings')->assertForbidden();$admin=User::factory()->admin()->create();$this->actingAs($admin)->put('/admin/settings/general',['marketplace_name'=>'New Market','tagline'=>'Fresh']);$this->assertSame('New Market',Setting::where(['group'=>'general','key'=>'marketplace_name'])->value('value'));$this->actingAs($admin)->put('/admin/settings/contact',['support_email'=>'bad'])->assertSessionHasErrors('support_email');} public function test_unknown_setting_cannot_be_created():void{$admin=User::factory()->admin()->create();$this->actingAs($admin)->put('/admin/settings/general',['stripe_secret'=>'no']);$this->assertDatabaseMissing('settings',['key'=>'stripe_secret']);}}
